from __future__ import annotations

import logging
import sys
from typing import Any

from .qwen3_runtime import (
    _torch_is_rocm,
)

_log = logging.getLogger("transub_engine.asr.qwen3_batch")

_ISLAND_BATCH_1P7 = 8


_ISLAND_BATCH_DEFAULT = 16


_ISLAND_BATCH_CAP_1P7 = 16


_ISLAND_BATCH_CAP_DEFAULT = 32


_SESSION_BATCH_CAP: dict[str, int] = {}
_SESSION_BATCH_OK: dict[str, int] = {}
# After this many successful batches at a reduced OOM cap, raise the cap.
_OOM_CAP_RECOVER_AFTER = 8
# Soft spoken-seconds budget per generate batch (avoids padded mega-batches).
_ISLAND_BATCH_MAX_SPOKEN_S = 48.0

# Longest/shortest duration allowed in one generate(). Wider mixes pad every
# clip to the long island and contaminate short neighbors into particles.
_ISLAND_BATCH_DURATION_RATIO = 2.5
_ISLAND_BATCH_RATIO_FLOOR_S = 0.05



_ISLAND_BATCH_CTX: dict[str, Any] = {}


def normalize_qwen_batch_mode(raw: str | None) -> str:
    """``auto`` | ``conservative`` | ``aggressive``."""
    v = str(raw or "auto").strip().lower()
    if v in ("conservative", "safe", "low"):
        return "conservative"
    if v in ("aggressive", "fast", "high"):
        return "aggressive"
    return "auto"


def _is_17b_asr_model(asr_model: str | None) -> bool:
    return "1.7" in str(asr_model or "").lower()


def _legacy_island_batch_size(asr_model: str | None) -> int:
    if _is_17b_asr_model(asr_model):
        return _ISLAND_BATCH_1P7
    return _ISLAND_BATCH_DEFAULT


def _probe_gpu_free_mib() -> tuple[int | None, int | None]:
    """Best-effort (free_mib, total_mib). Avoid importing torch unless already loaded."""
    import sys

    if "torch" in sys.modules:
        try:
            torch = sys.modules["torch"]
            if torch.cuda.is_available():
                free_b, total_b = torch.cuda.mem_get_info(0)
                return int(free_b // (1024 * 1024)), int(total_b // (1024 * 1024))
        except Exception:
            pass
    try:
        from ..device import detect_device

        total = int(detect_device().get("vramMb") or 0)
        if total > 0:
            return None, total
    except Exception:
        pass
    return None, None


def _resolve_vram_mib(
    *,
    job_gpu_free_mib: int | None = None,
    job_gpu_total_mib: int | None = None,
) -> tuple[int | None, int | None]:
    """Prefer shell pre-job sample; fall back to torch/detect_device probe."""
    free_mib, total_mib = _probe_gpu_free_mib()
    try:
        jf = int(job_gpu_free_mib) if job_gpu_free_mib is not None else None
        if jf is not None and jf > 0:
            free_mib = jf
    except (TypeError, ValueError):
        pass
    try:
        jt = int(job_gpu_total_mib) if job_gpu_total_mib is not None else None
        if jt is not None and jt > 0:
            total_mib = jt
    except (TypeError, ValueError):
        pass
    return free_mib, total_mib


def _asr_runs_on_cuda(device: str) -> bool:
    d = str(device or "auto").strip().lower()
    if d == "cpu":
        return False
    if d == "cuda":
        return True
    try:
        from ..device import detect_device

        info = detect_device()
        return bool(info.get("hasCuda") or info.get("hasRocm") or info.get("hasXpu"))
    except Exception:
        return False


def _auto_batch_from_vram(
    *,
    is_17b: bool,
    free_mib: int | None,
    total_mib: int | None,
    headroom_frac: float = 0.55,
) -> int:
    avail = int(free_mib) if free_mib and free_mib > 0 else 0
    if avail <= 0 and total_mib and total_mib > 0:
        frac = max(0.35, min(0.90, float(headroom_frac)))
        avail = int(total_mib * frac)
    if avail <= 0:
        return _legacy_island_batch_size("1.7b" if is_17b else "0.6b")
    if is_17b:
        if avail >= 14000:
            return 16
        if avail >= 10000:
            return 12
        # 8–10GB cards often have ~8GB free after model load; 12 beats 8 with
        # OOM half-split still available (DLDSS-557: free≈8506 → was stuck at 8).
        if avail >= 8000:
            return 12
        if avail >= 7000:
            return 10
        if avail >= 5000:
            return 6
        return 4
    if avail >= 12000:
        return 32
    if avail >= 8000:
        return 24
    if avail >= 5000:
        return 16
    if avail >= 3000:
        return 12
    return 8


def _aggressive_batch_from_vram(
    *,
    is_17b: bool,
    free_mib: int | None,
    total_mib: int | None,
    auto_n: int,
    base: int,
    cap: int,
) -> int:
    """Push toward cap using optimistic headroom; OOM split still applies downstream."""
    opt = max(
        auto_n,
        _auto_batch_from_vram(
            is_17b=is_17b,
            free_mib=free_mib,
            total_mib=total_mib,
            headroom_frac=0.80,
        ),
    )
    total = int(total_mib or 0)
    if is_17b:
        if total >= 16000:
            opt = max(opt, 16)
        elif total >= 12000:
            opt = max(opt, 12)
        elif total >= 10000:
            opt = max(opt, 10)
    else:
        if total >= 12000:
            opt = max(opt, 32)
        elif total >= 8000:
            opt = max(opt, 24)
        elif total >= 6000:
            opt = max(opt, 20)
    return max(base, min(cap, opt))


def _batch_session_key(asr_model: str | None, device: str, batch_mode: str | None) -> str:
    return (
        f"{str(asr_model or '').strip()}|"
        f"{str(device or 'auto').strip().lower()}|"
        f"{normalize_qwen_batch_mode(batch_mode)}"
    )


def note_island_batch_oom_cap(
    asr_model: str | None,
    device: str,
    batch_mode: str | None,
    attempted_n: int,
) -> None:
    key = _batch_session_key(asr_model, device, batch_mode)
    prev = _SESSION_BATCH_CAP.get(key, 999)
    new_cap = max(1, int(attempted_n) // 2)
    _SESSION_BATCH_CAP[key] = min(prev, new_cap)
    _SESSION_BATCH_OK[key] = 0
    _log.warning(
        "Qwen island batch OOM cap: %s -> %d (attempted %d)",
        key,
        _SESSION_BATCH_CAP[key],
        attempted_n,
    )


def note_island_batch_success(
    asr_model: str | None,
    device: str,
    batch_mode: str | None,
    *,
    target_batch: int,
    used_batch: int,
) -> None:
    """Allow a reduced OOM cap to recover after sustained successful batches.

    Long jobs that trip one early OOM used to stay at 1–2 for the whole file;
    that multiplies wall-clock past ~2h. Recover gradually toward ``target_batch``.
    """
    key = _batch_session_key(asr_model, device, batch_mode)
    cap = _SESSION_BATCH_CAP.get(key)
    if cap is None:
        return
    target = max(1, int(target_batch))
    used = max(1, int(used_batch))
    if cap >= target:
        _SESSION_BATCH_CAP.pop(key, None)
        _SESSION_BATCH_OK.pop(key, None)
        return
    ok = int(_SESSION_BATCH_OK.get(key, 0)) + 1
    _SESSION_BATCH_OK[key] = ok
    if ok < int(_OOM_CAP_RECOVER_AFTER):
        return
    # Raise gently: +50% (ceil) or +1, never above target or what just succeeded * 2.
    bumped = min(target, max(cap + 1, (cap * 3 + 1) // 2, used + 1))
    if bumped <= cap:
        _SESSION_BATCH_OK[key] = 0
        return
    _SESSION_BATCH_CAP[key] = bumped
    _SESSION_BATCH_OK[key] = 0
    _log.info(
        "Qwen island batch OOM cap recover: %s -> %d (target %d)",
        key,
        bumped,
        target,
    )


def clear_island_batch_oom_caps() -> int:
    n = len(_SESSION_BATCH_CAP)
    _SESSION_BATCH_CAP.clear()
    _SESSION_BATCH_OK.clear()
    return n


def get_island_batch_oom_cap(
    asr_model: str | None,
    device: str,
    batch_mode: str | None,
) -> int | None:
    return _SESSION_BATCH_CAP.get(_batch_session_key(asr_model, device, batch_mode))


def limit_island_batch_by_spoken_s(
    frames: list[tuple[float, float]],
    start_idx: int,
    max_n: int,
    *,
    max_spoken_s: float | None = None,
) -> int:
    """How many frames to take from ``start_idx`` (at least 1 when any remain).

    Caps cumulative island duration so one generate() is not dominated by a
    handful of long padded clips (common OOM trigger on soft-AV).
    """
    remain = len(frames) - int(start_idx)
    if remain <= 0:
        return 0
    n = max(1, min(int(max_n), remain))
    budget = float(
        _ISLAND_BATCH_MAX_SPOKEN_S if max_spoken_s is None else max_spoken_s
    )
    if budget <= 0 or n <= 1:
        return n
    spoken = 0.0
    out = 0
    for i in range(int(start_idx), int(start_idx) + n):
        a, b = frames[i][0], frames[i][1]
        dur = max(0.0, float(b) - float(a))
        if out >= 1 and spoken + dur > budget:
            break
        spoken += dur
        out += 1
    return max(1, out)


def limit_island_batch_homogeneous(
    frames: list[tuple[float, float]],
    start_idx: int,
    max_n: int,
    *,
    max_spoken_s: float | None = None,
    max_duration_ratio: float | None = None,
) -> int:
    """How many time-ordered frames to take (at least 1 when any remain).

    Stops before a frame would exceed the spoken-seconds budget or make the
    batch longest/shortest duration ratio larger than ``max_duration_ratio``
    (default 2.5). A 5s line is not padded together with 0.4s breaths.
    Timeline order stays intact — mismatched islands wait for the next batch.
    """
    remain = len(frames) - int(start_idx)
    if remain <= 0:
        return 0
    n = max(1, min(int(max_n), remain))
    if n <= 1:
        return n
    budget = float(
        _ISLAND_BATCH_MAX_SPOKEN_S if max_spoken_s is None else max_spoken_s
    )
    ratio = float(
        _ISLAND_BATCH_DURATION_RATIO
        if max_duration_ratio is None
        else max_duration_ratio
    )
    if ratio < 1.0:
        ratio = 1.0
    floor = float(_ISLAND_BATCH_RATIO_FLOOR_S)
    spoken = 0.0
    out = 0
    d_min = 0.0
    d_max = 0.0
    for i in range(int(start_idx), int(start_idx) + n):
        a, b = frames[i][0], frames[i][1]
        dur = max(0.0, float(b) - float(a))
        shaped = max(floor, dur)
        if out >= 1:
            new_min = min(d_min, shaped)
            new_max = max(d_max, shaped)
            if new_min > 0 and (new_max / new_min) > ratio:
                break
            if budget > 0 and spoken + dur > budget:
                break
        spoken += dur
        d_min = shaped if out == 0 else min(d_min, shaped)
        d_max = shaped if out == 0 else max(d_max, shaped)
        out += 1
    return max(1, out)


def _set_island_batch_ctx(**kwargs: Any) -> None:
    _ISLAND_BATCH_CTX.clear()
    _ISLAND_BATCH_CTX.update(kwargs)


def _effective_batch_mode(
    batch_mode: str | None,
    perf_profile: str | None = None,
) -> str:
    mode = normalize_qwen_batch_mode(batch_mode)
    if str(perf_profile or "").strip().lower() == "speed":
        return "conservative"
    return mode


def resolve_island_batch_size(
    asr_model: str | None,
    *,
    batch_mode: str | None = "auto",
    device: str = "auto",
    perf_profile: str | None = None,
    job_gpu_free_mib: int | None = None,
    job_gpu_total_mib: int | None = None,
) -> int:
    """
    TEN/FireRed island batch count for ``model.transcribe([...])``.

    conservative: never above legacy 8/16; may shrink on tight VRAM.
    auto: VRAM-scaled (default).
    aggressive: up to 16/32 when VRAM allows.
    """
    mode = _effective_batch_mode(batch_mode, perf_profile)
    is_17b = _is_17b_asr_model(asr_model)
    base = _ISLAND_BATCH_1P7 if is_17b else _ISLAND_BATCH_DEFAULT
    cap = _ISLAND_BATCH_CAP_1P7 if is_17b else _ISLAND_BATCH_CAP_DEFAULT
    if not _asr_runs_on_cuda(device):
        return max(1, min(2, base // 4 or 1))
    # ROCm consumer GPUs (e.g. RX 9070 / gfx1201): keep island batch at 1 —
    # multi-item pads frequently hit hipErrorInvalidValue on Qwen3 generate.
    if _torch_is_rocm():
        return 1
    free_mib, total_mib = _resolve_vram_mib(
        job_gpu_free_mib=job_gpu_free_mib,
        job_gpu_total_mib=job_gpu_total_mib,
    )
    auto_n = max(1, min(cap, _auto_batch_from_vram(
        is_17b=is_17b,
        free_mib=free_mib,
        total_mib=total_mib,
    )))
    if mode == "conservative":
        n = max(1, min(base, auto_n))
    elif mode == "aggressive":
        n = _aggressive_batch_from_vram(
            is_17b=is_17b,
            free_mib=free_mib,
            total_mib=total_mib,
            auto_n=auto_n,
            base=base,
            cap=cap,
        )
    else:
        n = auto_n
    oom_cap = get_island_batch_oom_cap(asr_model, device, mode)
    if oom_cap is not None:
        n = min(n, max(1, int(oom_cap)))
    return max(1, n)


def _island_batch_size(asr_model: str | None) -> int:
    """Backward-compatible default (conservative legacy caps)."""
    return _legacy_island_batch_size(asr_model)
